import{_ as e,o,c as a,a2 as d}from"./chunks/framework.1C62pOns.js";const m=JSON.parse('{"title":"Planejador de Execução — ferramentas","description":"","frontmatter":{},"headers":[],"relativePath":"pt/funcoes/planejador.md","filePath":"pt/funcoes/planejador.md","lastUpdated":1787839708000}'),r={name:"pt/funcoes/planejador.md"};function n(i,t,s,c,l,p){return o(),a("div",null,[...t[0]||(t[0]=[d('<h1 id="planejador-de-execucao-—-ferramentas" tabindex="-1">Planejador de Execução — ferramentas <a class="header-anchor" href="#planejador-de-execucao-—-ferramentas" aria-label="Permalink to &quot;Planejador de Execução — ferramentas&quot;">​</a></h1><p>As operações que um Planejador pode acionar durante o loop. É uma lista <strong>liberada por você</strong> na tela do planejador: nada roda sem estar marcado ali.</p><p>Agentes e times NÃO aparecem aqui — eles são acionados pelos <strong>executores</strong> cadastrados no planejador, que é o catálogo que o modelo enxerga na hora de montar o plano.</p><p>Estão disponíveis <strong>18</strong> símbolos neste contexto.</p><h2 id="banco-de-dados" tabindex="-1">Banco de dados <a class="header-anchor" href="#banco-de-dados" aria-label="Permalink to &quot;Banco de dados&quot;">​</a></h2><h3 id="db-delete-database-connection-id-int-table-str-where-dict" tabindex="-1"><code>db_delete(database_connection_id: int, table: str, where: dict)</code> <a class="header-anchor" href="#db-delete-database-connection-id-int-table-str-where-dict" aria-label="Permalink to &quot;`db_delete(database_connection_id: int, table: str, where: dict)`&quot;">​</a></h3><p>Remove registros de uma tabela da conexão de banco cadastrada.</p><p>Args: database_connection_id: ID da DatabaseConnection cadastrada no ProAgent Hub table: nome da tabela (ex: &#39;app.my_table&#39;) where: dicionário coluna → valor para filtro (cláusula WHERE) user_name: usuário da plataforma para autorização (padrão: &#39;projjetta&#39;)</p><p>Returns: número de linhas afetadas</p><p>Exemplo::</p><pre><code>rows = db_delete(1, &quot;app.my_table&quot;, {&quot;id&quot;: 42})\n</code></pre><table tabindex="0"><thead><tr><th>Parâmetro</th><th>Tipo</th><th>Padrão</th></tr></thead><tbody><tr><td><code>database_connection_id</code></td><td>int</td><td><strong>obrigatório</strong></td></tr><tr><td><code>table</code></td><td>str</td><td><strong>obrigatório</strong></td></tr><tr><td><code>where</code></td><td>dict</td><td><strong>obrigatório</strong></td></tr></tbody></table><h3 id="db-insert-database-connection-id-int-table-str-values-dict" tabindex="-1"><code>db_insert(database_connection_id: int, table: str, values: dict)</code> <a class="header-anchor" href="#db-insert-database-connection-id-int-table-str-values-dict" aria-label="Permalink to &quot;`db_insert(database_connection_id: int, table: str, values: dict)`&quot;">​</a></h3><p>Insere um registro em uma tabela da conexão de banco cadastrada.</p><p>Args: database_connection_id: ID da DatabaseConnection cadastrada no ProAgent Hub table: nome da tabela (ex: &#39;app.my_table&#39;) values: dicionário coluna → valor a ser inserido user_name: usuário da plataforma para autorização (padrão: &#39;projjetta&#39;)</p><p>Returns: número de linhas afetadas</p><p>Exemplo::</p><pre><code>rows = db_insert(1, &quot;app.my_table&quot;, {&quot;name&quot;: &quot;João&quot;, &quot;age&quot;: 30})\n</code></pre><table tabindex="0"><thead><tr><th>Parâmetro</th><th>Tipo</th><th>Padrão</th></tr></thead><tbody><tr><td><code>database_connection_id</code></td><td>int</td><td><strong>obrigatório</strong></td></tr><tr><td><code>table</code></td><td>str</td><td><strong>obrigatório</strong></td></tr><tr><td><code>values</code></td><td>dict</td><td><strong>obrigatório</strong></td></tr></tbody></table><h3 id="db-query-database-connection-id-int-query-str-chunk-size-int-1000-query-params-dict-none" tabindex="-1"><code>db_query(database_connection_id: int, query: str, chunk_size: int = 1000, query_params: dict = None)</code> <a class="header-anchor" href="#db-query-database-connection-id-int-query-str-chunk-size-int-1000-query-params-dict-none" aria-label="Permalink to &quot;`db_query(database_connection_id: int, query: str, chunk_size: int = 1000, query_params: dict = None)`&quot;">​</a></h3><p>Executa uma query SELECT em uma conexão de banco cadastrada na plataforma.</p><p>Args: database_connection_id: ID da DatabaseConnection cadastrada no ProAgent Hub query: SQL a ser executado (use :param para bind variables) chunk_size: tamanho de cada lote retornado pelo cursor (padrão: 1000) query_params: dicionário de parâmetros para bind variables (opcional) user_name: usuário da plataforma para autorização (padrão: &#39;projjetta&#39;)</p><p>Returns: lista de dicionários com os registros retornados</p><p>Exemplo::</p><pre><code>rows = db_query(1, &quot;SELECT id, name FROM app.user WHERE id &gt; :min_id&quot;, query_params={&quot;min_id&quot;: 10})\n</code></pre><table tabindex="0"><thead><tr><th>Parâmetro</th><th>Tipo</th><th>Padrão</th></tr></thead><tbody><tr><td><code>database_connection_id</code></td><td>int</td><td><strong>obrigatório</strong></td></tr><tr><td><code>query</code></td><td>str</td><td><strong>obrigatório</strong></td></tr><tr><td><code>chunk_size</code></td><td>int</td><td>1000</td></tr><tr><td><code>query_params</code></td><td>dict</td><td>None</td></tr></tbody></table><h3 id="db-update-database-connection-id-int-table-str-values-dict-where-dict" tabindex="-1"><code>db_update(database_connection_id: int, table: str, values: dict, where: dict)</code> <a class="header-anchor" href="#db-update-database-connection-id-int-table-str-values-dict-where-dict" aria-label="Permalink to &quot;`db_update(database_connection_id: int, table: str, values: dict, where: dict)`&quot;">​</a></h3><p>Atualiza registros em uma tabela da conexão de banco cadastrada.</p><p>Args: database_connection_id: ID da DatabaseConnection cadastrada no ProAgent Hub table: nome da tabela (ex: &#39;app.my_table&#39;) values: dicionário coluna → novo valor where: dicionário coluna → valor para filtro (cláusula WHERE) user_name: usuário da plataforma para autorização (padrão: &#39;projjetta&#39;)</p><p>Returns: número de linhas afetadas</p><p>Exemplo::</p><pre><code>rows = db_update(1, &quot;app.my_table&quot;, {&quot;age&quot;: 31}, {&quot;name&quot;: &quot;João&quot;})\n</code></pre><table tabindex="0"><thead><tr><th>Parâmetro</th><th>Tipo</th><th>Padrão</th></tr></thead><tbody><tr><td><code>database_connection_id</code></td><td>int</td><td><strong>obrigatório</strong></td></tr><tr><td><code>table</code></td><td>str</td><td><strong>obrigatório</strong></td></tr><tr><td><code>values</code></td><td>dict</td><td><strong>obrigatório</strong></td></tr><tr><td><code>where</code></td><td>dict</td><td><strong>obrigatório</strong></td></tr></tbody></table><h3 id="db-upsert-database-connection-id-int-table-str-values-dict-where-dict" tabindex="-1"><code>db_upsert(database_connection_id: int, table: str, values: dict, where: dict)</code> <a class="header-anchor" href="#db-upsert-database-connection-id-int-table-str-values-dict-where-dict" aria-label="Permalink to &quot;`db_upsert(database_connection_id: int, table: str, values: dict, where: dict)`&quot;">​</a></h3><p>Insere ou atualiza um registro em uma tabela da conexão de banco cadastrada.</p><p>A estratégia de upsert depende do banco (MERGE, ON CONFLICT, ON DUPLICATE KEY).</p><p>Args: database_connection_id: ID da DatabaseConnection cadastrada no ProAgent Hub table: nome da tabela (ex: &#39;app.my_table&#39;) values: dicionário coluna → valor com todos os campos (chaves + dados) where: dicionário coluna → valor com as colunas-chave para o ON/CONFLICT user_name: usuário da plataforma para autorização (padrão: &#39;projjetta&#39;)</p><p>Returns: número de linhas afetadas</p><p>Exemplo::</p><pre><code>rows = db_upsert(1, &quot;app.my_table&quot;, {&quot;id&quot;: 1, &quot;name&quot;: &quot;João&quot;, &quot;age&quot;: 30}, {&quot;id&quot;: 1})\n</code></pre><table tabindex="0"><thead><tr><th>Parâmetro</th><th>Tipo</th><th>Padrão</th></tr></thead><tbody><tr><td><code>database_connection_id</code></td><td>int</td><td><strong>obrigatório</strong></td></tr><tr><td><code>table</code></td><td>str</td><td><strong>obrigatório</strong></td></tr><tr><td><code>values</code></td><td>dict</td><td><strong>obrigatório</strong></td></tr><tr><td><code>where</code></td><td>dict</td><td><strong>obrigatório</strong></td></tr></tbody></table><h2 id="arquivos" tabindex="-1">Arquivos <a class="header-anchor" href="#arquivos" aria-label="Permalink to &quot;Arquivos&quot;">​</a></h2><h3 id="list-dir-directory-str-recursive-bool-false-extension-filter-str" tabindex="-1"><code>list_dir(directory: str, recursive: bool = False, extension_filter: str = &#39;&#39;)</code> <a class="header-anchor" href="#list-dir-directory-str-recursive-bool-false-extension-filter-str" aria-label="Permalink to &quot;`list_dir(directory: str, recursive: bool = False, extension_filter: str = &#39;&#39;)`&quot;">​</a></h3><p>Lista arquivos de um diretório, opcionalmente recursivo e filtrando por regex.</p><p>Args: directory: caminho do diretório recursive: True para percorrer subdiretórios extension_filter: regex aplicado ao nome do arquivo (ex.: <code>\\.csv$</code>); vazio = todos</p><p>Returns: lista ordenada de caminhos absolutos de arquivo</p><p>Raises: NotADirectoryError: se o diretório não existir re.error: se o <code>extension_filter</code> for um regex inválido</p><table tabindex="0"><thead><tr><th>Parâmetro</th><th>Tipo</th><th>Padrão</th></tr></thead><tbody><tr><td><code>directory</code></td><td>str</td><td><strong>obrigatório</strong></td></tr><tr><td><code>recursive</code></td><td>bool</td><td>False</td></tr><tr><td><code>extension_filter</code></td><td>str</td><td>&#39;&#39;</td></tr></tbody></table><h3 id="read-file-file-path-str-file-format-str-csv-encoding-str-utf-8-delimiter-str" tabindex="-1"><code>read_file(file_path: str, file_format: str = &#39;csv&#39;, encoding: str = &#39;utf-8&#39;, delimiter: str = &#39;,&#39;)</code> <a class="header-anchor" href="#read-file-file-path-str-file-format-str-csv-encoding-str-utf-8-delimiter-str" aria-label="Permalink to &quot;`read_file(file_path: str, file_format: str = &#39;csv&#39;, encoding: str = &#39;utf-8&#39;, delimiter: str = &#39;,&#39;)`&quot;">​</a></h3><p>Lê um arquivo e retorna os dados conforme o formato.</p><p>Args: file_path: caminho do arquivo file_format: &#39;csv&#39; | &#39;json&#39; | &#39;xlsx&#39; | &#39;txt&#39; encoding: codificação do arquivo (padrão &#39;utf-8&#39;) delimiter: separador de colunas para CSV (padrão &#39;,&#39;)</p><p>Returns: lista de dicts (csv/xlsx), objeto JSON (json) ou string (txt)</p><table tabindex="0"><thead><tr><th>Parâmetro</th><th>Tipo</th><th>Padrão</th></tr></thead><tbody><tr><td><code>file_path</code></td><td>str</td><td><strong>obrigatório</strong></td></tr><tr><td><code>file_format</code></td><td>str</td><td>&#39;csv&#39;</td></tr><tr><td><code>encoding</code></td><td>str</td><td>&#39;utf-8&#39;</td></tr><tr><td><code>delimiter</code></td><td>str</td><td>&#39;,&#39;</td></tr></tbody></table><h3 id="write-file-file-path-str-data-file-format-str-csv-encoding-str-utf-8-delimiter-str-mode-str-w" tabindex="-1"><code>write_file(file_path: str, data, file_format: str = &#39;csv&#39;, encoding: str = &#39;utf-8&#39;, delimiter: str = &#39;,&#39;, mode: str = &#39;w&#39;)</code> <a class="header-anchor" href="#write-file-file-path-str-data-file-format-str-csv-encoding-str-utf-8-delimiter-str-mode-str-w" aria-label="Permalink to &quot;`write_file(file_path: str, data, file_format: str = &#39;csv&#39;, encoding: str = &#39;utf-8&#39;, delimiter: str = &#39;,&#39;, mode: str = &#39;w&#39;)`&quot;">​</a></h3><p>Escreve dados em um arquivo conforme o formato.</p><p>Args: file_path: caminho do arquivo (diretórios pais são criados se necessário) data: dados a gravar (lista de dicts para csv/json, qualquer coisa p/ txt) file_format: &#39;csv&#39; | &#39;json&#39; | &#39;txt&#39; encoding: codificação do arquivo (padrão &#39;utf-8&#39;) delimiter: separador de colunas para CSV (padrão &#39;,&#39;) mode: &#39;w&#39; para sobrescrever, &#39;a&#39; para anexar</p><table tabindex="0"><thead><tr><th>Parâmetro</th><th>Tipo</th><th>Padrão</th></tr></thead><tbody><tr><td><code>file_path</code></td><td>str</td><td><strong>obrigatório</strong></td></tr><tr><td><code>data</code></td><td>—</td><td><strong>obrigatório</strong></td></tr><tr><td><code>file_format</code></td><td>str</td><td>&#39;csv&#39;</td></tr><tr><td><code>encoding</code></td><td>str</td><td>&#39;utf-8&#39;</td></tr><tr><td><code>delimiter</code></td><td>str</td><td>&#39;,&#39;</td></tr><tr><td><code>mode</code></td><td>str</td><td>&#39;w&#39;</td></tr></tbody></table><h2 id="http" tabindex="-1">HTTP <a class="header-anchor" href="#http" aria-label="Permalink to &quot;HTTP&quot;">​</a></h2><h3 id="http-request-method-str-url-str-body-none-headers-dict-none-timeout-int-30" tabindex="-1"><code>http_request(method: str, url: str, body = None, headers: dict = None, timeout: int = 30)</code> <a class="header-anchor" href="#http-request-method-str-url-str-body-none-headers-dict-none-timeout-int-30" aria-label="Permalink to &quot;`http_request(method: str, url: str, body = None, headers: dict = None, timeout: int = 30)`&quot;">​</a></h3><p>Executa uma requisição HTTP e retorna o corpo da resposta.</p><p>Args: method: verbo HTTP (GET, POST, ...) url: URL de destino body: corpo da requisição — dict/list é enviado como JSON; str como dados brutos headers: dicionário de cabeçalhos (opcional) timeout: timeout em segundos (padrão 30)</p><p>Returns: o JSON da resposta quando possível, caso contrário o texto bruto</p><table tabindex="0"><thead><tr><th>Parâmetro</th><th>Tipo</th><th>Padrão</th></tr></thead><tbody><tr><td><code>method</code></td><td>str</td><td><strong>obrigatório</strong></td></tr><tr><td><code>url</code></td><td>str</td><td><strong>obrigatório</strong></td></tr><tr><td><code>body</code></td><td>—</td><td>None</td></tr><tr><td><code>headers</code></td><td>dict</td><td>None</td></tr><tr><td><code>timeout</code></td><td>int</td><td>30</td></tr></tbody></table><h2 id="e-mail" tabindex="-1">E-mail <a class="header-anchor" href="#e-mail" aria-label="Permalink to &quot;E-mail&quot;">​</a></h2><h3 id="send-email-to-email-str-subject-str-body-str-from-email-str-none-attachments-list-none" tabindex="-1"><code>send_email(to_email: str, subject: str, body: str, from_email: str = None, attachments: list = None)</code> <a class="header-anchor" href="#send-email-to-email-str-subject-str-body-str-from-email-str-none-attachments-list-none" aria-label="Permalink to &quot;`send_email(to_email: str, subject: str, body: str, from_email: str = None, attachments: list = None)`&quot;">​</a></h3><p>Envia um e-mail usando as configurações SMTP do sistema.</p><p>Args: to_email: endereço de destino subject: assunto do e-mail body: corpo do e-mail from_email: remetente alternativo (opcional) attachments: lista de caminhos de arquivo para anexar (opcional)</p><table tabindex="0"><thead><tr><th>Parâmetro</th><th>Tipo</th><th>Padrão</th></tr></thead><tbody><tr><td><code>to_email</code></td><td>str</td><td><strong>obrigatório</strong></td></tr><tr><td><code>subject</code></td><td>str</td><td><strong>obrigatório</strong></td></tr><tr><td><code>body</code></td><td>str</td><td><strong>obrigatório</strong></td></tr><tr><td><code>from_email</code></td><td>str</td><td>None</td></tr><tr><td><code>attachments</code></td><td>list</td><td>None</td></tr></tbody></table><h2 id="microsoft-graph" tabindex="-1">microsoft_graph <a class="header-anchor" href="#microsoft-graph" aria-label="Permalink to &quot;microsoft_graph&quot;">​</a></h2><h3 id="microsoft-graph-tenant-id-str-none-none-client-id-str-none-none-client-secret-str-none-none-env-prefix-str-ms-graph" tabindex="-1"><code>microsoft_graph(tenant_id: str | None = None, client_id: str | None = None, client_secret: str | None = None, env_prefix: str = &#39;MS_GRAPH_&#39;)</code> <a class="header-anchor" href="#microsoft-graph-tenant-id-str-none-none-client-id-str-none-none-client-secret-str-none-none-env-prefix-str-ms-graph" aria-label="Permalink to &quot;`microsoft_graph(tenant_id: str | None = None, client_id: str | None = None, client_secret: str | None = None, env_prefix: str = &#39;MS_GRAPH_&#39;)`&quot;">​</a></h3><p>Factory de MicrosoftGraphClient. Quando as credenciais não são passadas</p><p>explicitamente, são lidas das variáveis de ambiente <code>{env_prefix}TENANT_ID</code> / <code>{env_prefix}CLIENT_ID</code> / <code>{env_prefix}CLIENT_SECRET</code> (prefixo padrão <code>MS_GRAPH_</code>).</p><p>Workflows que usam seu próprio conjunto de credenciais devem passá-las diretamente, por exemplo::</p><pre><code>graph = microsoft_graph(\n    tenant_id=TENANT_ID, client_id=CLIENT_ID, client_secret=CLIENT_SECRET,\n)\n</code></pre><table tabindex="0"><thead><tr><th>Parâmetro</th><th>Tipo</th><th>Padrão</th></tr></thead><tbody><tr><td><code>tenant_id</code></td><td>str</td><td>None</td></tr><tr><td><code>client_id</code></td><td>str</td><td>None</td></tr><tr><td><code>client_secret</code></td><td>str</td><td>None</td></tr><tr><td><code>env_prefix</code></td><td>str</td><td>&#39;MS_GRAPH_&#39;</td></tr></tbody></table><h2 id="sistema" tabindex="-1">Sistema <a class="header-anchor" href="#sistema" aria-label="Permalink to &quot;Sistema&quot;">​</a></h2><h3 id="copy-file-source-str-destination-str" tabindex="-1"><code>copy_file(source: str, destination: str)</code> <a class="header-anchor" href="#copy-file-source-str-destination-str" aria-label="Permalink to &quot;`copy_file(source: str, destination: str)`&quot;">​</a></h3><p>Copia um arquivo de <code>source</code> para <code>destination</code> (preserva metadados).</p><table tabindex="0"><thead><tr><th>Parâmetro</th><th>Tipo</th><th>Padrão</th></tr></thead><tbody><tr><td><code>source</code></td><td>str</td><td><strong>obrigatório</strong></td></tr><tr><td><code>destination</code></td><td>str</td><td><strong>obrigatório</strong></td></tr></tbody></table><h3 id="file-info-path-str" tabindex="-1"><code>file_info(path: str)</code> <a class="header-anchor" href="#file-info-path-str" aria-label="Permalink to &quot;`file_info(path: str)`&quot;">​</a></h3><p>Retorna tamanho (bytes) e data de modificação (UTC ISO) de um arquivo.</p><table tabindex="0"><thead><tr><th>Parâmetro</th><th>Tipo</th><th>Padrão</th></tr></thead><tbody><tr><td><code>path</code></td><td>str</td><td><strong>obrigatório</strong></td></tr></tbody></table><h3 id="install-python-package-package-str-timeout-int-300" tabindex="-1"><code>install_python_package(package: str, timeout: int = 300)</code> <a class="header-anchor" href="#install-python-package-package-str-timeout-int-300" aria-label="Permalink to &quot;`install_python_package(package: str, timeout: int = 300)`&quot;">​</a></h3><p>Instala biblioteca(s) Python no ambiente atual (.venv) via pip.</p><p>Aceita especificação de versão (ex.: <code>pandas==2.2.0</code>). Retorna a saída do pip.</p><p>O pacote fica importável JÁ NESTA execução: o pip instala em disco, mas o processo em curso mantém em cache o conteúdo dos diretórios de <code>sys.path</code>, e sem invalidar esse cache o <code>import</code> seguinte ainda falharia com <code>ModuleNotFoundError</code> — instalar e continuar sem poder usar não serve para nada em um loop que instala justamente para usar em seguida.</p><table tabindex="0"><thead><tr><th>Parâmetro</th><th>Tipo</th><th>Padrão</th></tr></thead><tbody><tr><td><code>package</code></td><td>str</td><td><strong>obrigatório</strong></td></tr><tr><td><code>timeout</code></td><td>int</td><td>300</td></tr></tbody></table><h3 id="move-file-source-str-destination-str" tabindex="-1"><code>move_file(source: str, destination: str)</code> <a class="header-anchor" href="#move-file-source-str-destination-str" aria-label="Permalink to &quot;`move_file(source: str, destination: str)`&quot;">​</a></h3><p>Renomeia ou move um arquivo/pasta de <code>source</code> para <code>destination</code>.</p><table tabindex="0"><thead><tr><th>Parâmetro</th><th>Tipo</th><th>Padrão</th></tr></thead><tbody><tr><td><code>source</code></td><td>str</td><td><strong>obrigatório</strong></td></tr><tr><td><code>destination</code></td><td>str</td><td><strong>obrigatório</strong></td></tr></tbody></table><h3 id="run-python-code-code-str-timeout-int-300" tabindex="-1"><code>run_python_code(code: str, timeout: int = 300)</code> <a class="header-anchor" href="#run-python-code-code-str-timeout-int-300" aria-label="Permalink to &quot;`run_python_code(code: str, timeout: int = 300)`&quot;">​</a></h3><p>Executa código Python dinâmico e retorna o stdout (ou o traceback do erro).</p><p>Se a ÚLTIMA linha do código for uma expressão, o valor dela também entra na saída — como num notebook. Quem gera o código costuma terminar com o nome da variável do resultado (<code>valores</code>) esperando recebê-lo de volta; sem isso o <code>exec</code> descartava o valor em silêncio e a resposta vinha vazia, o que é indistinguível de &quot;não achei nada&quot; para quem chamou.</p><p><code>scope</code> é preenchido pela PLATAFORMA (nunca por quem escreve o código) com as funções que o chamador libera — é assim que o planejador entrega <code>db_query</code>, <code>db_insert</code> e companhia já prontas, com a conexão cadastrada. Sem isso o código não tinha como falar com o banco e o modelo acabava inventando um <code>psycopg2.connect</code> com usuário e senha imaginários.</p><p><code>timeout</code> fecha um buraco que as irmãs já não tinham (<code>run_shell_command</code> para em 120s, <code>install_python_package</code> em 300s): um <code>while True</code> ou um <code>requests</code> sem timeout escrito pelo modelo travava a execução inteira. O planejador só verifica os limites ENTRE passos, então um passo que não volta nunca é um loop que não termina — e, na API, um worker do gunicorn preso.</p><p>A execução roda em uma thread própria e, esgotado o prazo, ela é <strong>abandonada</strong>, não morta: Python não interrompe uma thread com segurança. Quem chama recupera o controle e pode replanejar; o código largado segue até terminar sozinho (e morre com o processo, por ser daemon). É a troca honesta — abandonar uma thread é ruim, ficar preso para sempre é pior.</p><p>Use para cálculos, parsing ou transformações pontuais. Não execute código derivado de conteúdo não confiável.</p><table tabindex="0"><thead><tr><th>Parâmetro</th><th>Tipo</th><th>Padrão</th></tr></thead><tbody><tr><td><code>code</code></td><td>str</td><td><strong>obrigatório</strong></td></tr><tr><td><code>timeout</code></td><td>int</td><td>300</td></tr></tbody></table><h3 id="run-shell-command-command-str-timeout-int-120" tabindex="-1"><code>run_shell_command(command: str, timeout: int = 120)</code> <a class="header-anchor" href="#run-shell-command-command-str-timeout-int-120" aria-label="Permalink to &quot;`run_shell_command(command: str, timeout: int = 120)`&quot;">​</a></h3><p>Executa um comando do sistema operacional e retorna <code>exit</code> + saída.</p><p>Ex.: <code>ls</code>, <code>cp</code>, <code>mv</code>. Não execute comandos derivados de conteúdo não confiável.</p><table tabindex="0"><thead><tr><th>Parâmetro</th><th>Tipo</th><th>Padrão</th></tr></thead><tbody><tr><td><code>command</code></td><td>str</td><td><strong>obrigatório</strong></td></tr><tr><td><code>timeout</code></td><td>int</td><td>120</td></tr></tbody></table><h2 id="whatsapp" tabindex="-1">WhatsApp <a class="header-anchor" href="#whatsapp" aria-label="Permalink to &quot;WhatsApp&quot;">​</a></h2><h3 id="send-whatsapp-to-str-message-str-none-integration-id-int-none-instance-name-str-none-template-str-none-params-dict-none-timeout-int-30" tabindex="-1"><code>send_whatsapp(to: str, message: str = None, integration_id: int = None, instance_name: str = None, template: str = None, params: dict = None, timeout: int = 30)</code> <a class="header-anchor" href="#send-whatsapp-to-str-message-str-none-integration-id-int-none-instance-name-str-none-template-str-none-params-dict-none-timeout-int-30" aria-label="Permalink to &quot;`send_whatsapp(to: str, message: str = None, integration_id: int = None, instance_name: str = None, template: str = None, params: dict = None, timeout: int = 30)`&quot;">​</a></h3><p>Envia uma mensagem de texto no WhatsApp via Evolution API.</p><p>Args: to: número/JID de destino (ex.: &#39;5551999999999&#39; ou &#39;...@g.us&#39; para grupo) message: texto a enviar (preferido) integration_id: ID da WhatsAppIntegration a usar (opcional) instance_name: instance_name da integração (opcional) template: nome de template (fallback quando <code>message</code> não é informado) params: dicionário de parâmetros (renderizados no texto do fallback) timeout: timeout HTTP em segundos (padrão 30) user_name: usuário da plataforma (reservado para futura autorização)</p><p>Returns: dict com <code>status</code> e <code>to</code>. Levanta exceção em caso de falha de envio.</p><p>Exemplo::</p><pre><code>send_whatsapp(to=&quot;5551999999999&quot;, message=&quot;Proposta de agenda pronta.&quot;)\n</code></pre><table tabindex="0"><thead><tr><th>Parâmetro</th><th>Tipo</th><th>Padrão</th></tr></thead><tbody><tr><td><code>to</code></td><td>str</td><td><strong>obrigatório</strong></td></tr><tr><td><code>message</code></td><td>str</td><td>None</td></tr><tr><td><code>integration_id</code></td><td>int</td><td>None</td></tr><tr><td><code>instance_name</code></td><td>str</td><td>None</td></tr><tr><td><code>template</code></td><td>str</td><td>None</td></tr><tr><td><code>params</code></td><td>dict</td><td>None</td></tr><tr><td><code>timeout</code></td><td>int</td><td>30</td></tr></tbody></table>',110)])])}const h=e(r,[["render",n]]);export{m as __pageData,h as default};
